"""Strip the working `note` fields from refs/refs_iss.bib -> refs_iss_clean.bib.

refs_iss.bib carries a Chinese `note` on every entry recording where in the
source documents the work is cited.  Useful while writing, fatal if compiled
into a manuscript, so the manuscript uses the clean file.  Regenerate after any
change to refs_iss.bib.
"""
from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "refs" / "refs_iss.bib"
DST = ROOT / "refs" / "refs_iss_clean.bib"

HEADER = (
    "% refs_iss_clean.bib -- AUTO-GENERATED by scripts/make_clean_bib.py\n"
    "% Identical to refs/refs_iss.bib with the working `note` fields removed.\n"
    "% Do not edit: edit refs/refs_iss.bib and regenerate.\n"
)

text = SRC.read_text(encoding="utf-8")
out, i, n = [], 0, len(text)
while i < n:
    if re.match(r"note\s*=\s*\{", text[i:]):        # multi-line note field
        k, depth = text.index("{", i), 0
        while k < n:
            if text[k] == "{":
                depth += 1
            elif text[k] == "}":
                depth -= 1
                if depth == 0:
                    break
            k += 1
        end = k + 1
        while end < n and text[end] in " \t":
            end += 1
        if end < n and text[end] == ",":
            end += 1
        if end < n and text[end] == "\n":
            end += 1
        i = end
        continue
    out.append(text[i])
    i += 1

body = re.sub(r"\n{3,}", "\n\n", "".join(out))
lines = body.split("\n")
while lines and lines[0].lstrip().startswith("%"):      # drop the old header
    lines.pop(0)
body = "\n".join(lines).lstrip("\n")

DST.write_text(HEADER + "\n" + body, encoding="utf-8")
print(f"wrote {DST.name}: {body.count(chr(10) + '@')} entries, {len(body)} bytes")
